dowildbattle
clearflag FLAG_SYS_CTRL_OBJ_DELETE
specialvar VAR_RESULT GetBattleOutcome
goto_if_eq VAR_RESULT B_OUTCOME_WON EventScript_RemoveKecleon
goto_if_eq VAR_RESULT B_OUTCOME_RAN EventScript_RemoveKecleon
